q_r_pairs = [
    (3, 797), (13, 787), (31, 769), (43, 757), (61, 739), (67, 733),
    (73, 727), (109, 691), (127, 673), (139, 661), (157, 643), (181, 619),
    (193, 607), (199, 601), (223, 577), (229, 571), (277, 523), (313, 487),
    (337, 463), (367, 433), (379, 421)
]

solutions = []

for q, r in q_r_pairs:
    prime_p_candidates = [p for p in range(2, q, 1) if is_prime(p)]

    for p in prime_p_candidates:
        # Check P2 = 800 - p
        P2 = 800 - p
        if not is_prime(P2):
            continue

        # Check P4 = 800 + p
        P4 = 800 + p
        if not is_prime(P4):
            continue

        # Check P1 = p + 2q - 800
        P1 = p + 2*q - 800
        if not is_prime(P1):
            continue

        # Check P3 = 800 + p - 2q
        P3 = 800 + p - 2*q
        if not is_prime(P3):
            continue

        # All conditions met
        solutions.append((p, q, r))

print("Solutions (p, q, r) found in Case 2 (q+r=800):")
for sol in solutions:
    print(sol)
